"""Collect the complete measured suite and update only our SUMMARY section."""
import csv,hashlib,json,os,shutil,subprocess,sys,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];PUB=Path('/data1/liuyeqiang/damot_ics_followup_publish_20261029');DEST=PUB/'experiments/ics_followup_20261029';PY=str(ROOT/'env/bin/python')
sys.path.insert(0,str(ROOT/'code/tools/run'))
from apr_complement_experiment import Config,sha
from protocol import write_json,write_views
from stage_runtime_publication import copy,selected
from build_result_tables import read,METRICS,DOMAINS

def markdown(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(str(x) for x in row)+' |' for row in rows])
def n(x,places=3):return ('%.'+str(places)+'f')%float(x)
def configuration(name,stage=4):
    if name=='F':return Path('/data1/liuyeqiang/damot_rebuttal_20261026/configs')/('F_stage%d_e5_embedded.py'%stage)
    return Path('/data1/liuyeqiang/damot_apr_complement_hf_20261028_1420' if name=='HF' else '/data1/liuyeqiang/damot_apr_complement_hf_nogeom_20261029_1443')/'configs'/('stage%d.py'%stage)
def main():
    assert (ROOT/'manifests/experiments_complete.json').exists(),'Experiment queue is still incomplete'
    subprocess.check_call([PY,str(ROOT/'scripts/build_result_tables.py')]);subprocess.check_call([PY,str(ROOT/'scripts/report_drift.py')])
    for folder in (ROOT/'results').glob('analysis_*'):
        assert (folder/'summary.json').exists(),folder
        label=json.loads((folder/'summary.json').read_text())['protocol']['args']['label']
        cfgpath=ROOT/'results/S5'/('HF_'+label[-1])/'config.py' if label.startswith('S5_') else configuration(label.split('_stage')[0])
        write_views(Config.fromfile(str(cfgpath)),folder/'resolved_views.txt',dict(offline_feature_geometry='fixed',training_pipelines_are_provenance=True))
        selected(folder,PUB/'experiments/ics_probe'/folder.name)
    selected(ROOT/'results/S1',DEST/'S1_config_audit');selected(ROOT/'results/drift_decomposition',PUB/'experiments/ics_probe/drift_decomposition');selected(ROOT/'results/combined_tables',DEST/'tables')
    for name in ['F','HF']:
        cfg=Config.fromfile(str(configuration(name)))
        for cell in (ROOT/'results/S4'/name).glob('*/*/complete.json'):
            write_views(cfg,cell.parent/'resolved_views.txt',dict(inference='native tracker; cached FP32 detections/embeddings',projection_no_renormalization=True,cell_configuration='resolved_config.py or audit metadata'))
        selected(ROOT/'results/S4'/name,DEST/'S4'/name)
        for domain in DOMAINS:
            for meta in ['load.json','complete.json','resolved_config.py']:copy(ROOT/'cache/S4'/name/domain/meta,DEST/'S4'/name/'capture_metadata'/domain/meta)
    for group in 'abcd':
        path=ROOT/'results/S5'/('HF_'+group)
        assert sorted(p.name for p in (path/'episode/adapt').iterdir() if p.is_dir())==['stage04_after_night']
        selected(path,DEST/'S5'/('HF_'+group))
    for folder in (ROOT/'results/feats').iterdir():
        if folder.is_dir():
            for meta in folder.glob('*meta.json'):copy(meta,DEST/'metadata'/folder.name/meta.name)
    selected(ROOT/'logs',DEST/'logs')
    # Full source archives stay on the server; all method files are in Git.
    for meta in (ROOT/'manifests').glob('*'):
        if meta.is_file() and meta.suffix in ['.json','.txt'] and not meta.name.startswith('publication_'):copy(meta,DEST/'provenance'/meta.name)
    for model in ['F','HF','NOGEOM']:
        for stage in range(1,5):copy(configuration(model,stage),DEST/'configs'/model/('stage%d.py'%stage))
    for name,source in [('HF',Path('/data1/liuyeqiang/damot_apr_complement_hf_20261028_1420')),('NOGEOM',Path('/data1/liuyeqiang/damot_apr_complement_hf_nogeom_20261029_1443'))]:
        copy(source/'results/stage_domain_metrics.csv',DEST/'reference'/name/'stage_domain_metrics.csv')
        for stage in [3,4]:
            for domain in DOMAINS[:stage]:
                for file in ['metrics.csv','complete.json','used_config.py','load.json']:copy(source/'results'/('stage%d'%stage)/domain/file,DEST/'reference'/name/('stage%d'%stage)/domain/file)
    for script in (ROOT/'scripts').glob('*.py'):copy(script,DEST/'scripts'/script.name)
    for f in (ROOT/'code/tools/analysis').glob('ics_probe_*.py'):copy(f,PUB/'tools/analysis'/f.name)
    for f in (ROOT/'code/tools/run').glob('ics_*.py'):copy(f,PUB/'tools/run'/f.name)
    C=read(ROOT/'results/combined_tables/table_C_subspaces.csv');D=read(ROOT/'results/combined_tables/table_D_scan.csv');F=read(ROOT/'results/combined_tables/table_F_four_domain_means.csv');G=read(ROOT/'results/combined_tables/table_G_summary.csv')
    code=(ROOT/'manifests/code_commit.txt').read_text().strip()
    lines=['<!-- ICS_FOLLOWUP_BEGIN -->','# DAMOT ICS follow-up — completed measured results','',f'Run: `{ROOT}`. Method/runtime source commit: `{code}`. Probe/split seed: 0; S4 random-basis seed: 9973; S5 training seed: 1790355234. Per-job source fingerprints, effective configurations, checkpoint paths and hashes are delivered in `ics_followup_20261029/provenance/`, `configs/`, and `metadata/`.','', 'Scope: S1–S4 use frozen checkpoints and offline probes. S5 trains only the Night stage for two epochs from the same HF stage3 epoch5 checkpoint. Stages1–3 are skipped. The optional NOGEOM short-training repeat is not part of the primary four-group run.','','## Table C — actual stored subspace properties','',markdown(['Model','Domain energy %','Identity energy %','Weather/Identity','Weather-oracle angles °','E weather bAcc %','E night/clear bAcc %'],[[r['model'],n(100*float(r['weather_energy']),2),n(100*float(r['identity_energy']),2),n(r['weather_identity_ratio']),n(r['angle_weather_1_deg'],2)+' / '+n(r['angle_weather_2_deg'],2),n(100*float(r['E_weather_bacc']),2),n(100*float(r['E_night_clear_bacc']),2)] for r in C]),'', 'Source: `ics_followup_20261029/tables/table_C_subspaces.csv` and every `ics_probe/analysis_*_v2/csv/`. F/HF/NOGEOM use stage4 epoch5; S5 uses the four stage4 epoch2 endpoints. Run, seeds and source commit are above. Unpaired BDD domain offsets include scene and identity differences. Both principal angles are shown.','','## Table D — negative-control k scan','', 'Fixed display slice beta=1. The full 234-cell CSV retains beta=0/.5/1, every basis, effective rank, raw Fisher ratio and ten-random-basis mean/SD. Actual stored bank_pcs and covariance eigenvectors are separate families; the unchanged one-degree equivalence test is recorded for every model.','',''+markdown(['Model','Basis','k / rank','ID mAP %','Weather bAcc %','Raw Fisher'],[[r['model'],r['subspace'],r['k_requested']+' / '+r['k_effective'],n(100*float(r['id_mAP'])),n(100*float(r['weather_bacc'])),n(r['weather_fisher'],6)] for r in D if float(r['beta'])==1]),'', 'Source: `ics_followup_20261029/tables/table_D_scan.csv`. Checkpoints: F/HF/NOGEOM stage4 epoch5; car/test, split seed0, source commit and run above. Fisher is computed before any new row normalization. The refitted weather classifier keeps the original L2-input convention.','','## Table E — drift and attribution','']
    E=[]
    for name in ['F','HF','NOGEOM']:
        drift=read(ROOT/'results/drift_decomposition'/name/'drift_energy.csv');bank=next(r for r in drift if r['from_stage']=='3' and r['to_stage']=='4' and r['bucket']=='old' and r['basis']=='ICS stored bank_pcs')
        before=[r for r in read(ROOT/'results/drift_decomposition'/name/'cross_stage_retrieval.csv') if r['query_stage']=='4'];restore=read(ROOT/'results/drift_decomposition'/name/'drift_restoration.csv')
        vals=[]
        for basis,k in [('FAP residual PCA',2),('FAP residual PCA',16),('Identity oracle',2),('Identity oracle',16)]:vals.append(n(100*sum(float(r['forgetting_restored']) for r in restore if r['query_stage']=='4' and r['basis']==basis and int(r['k_requested'])==k)/3))
        E.append([name,n(bank['mean_in_sq'],6),n(bank['mean_out_sq'],6),n(100*sum(float(r['forgetting_proxy']) for r in before)/3)]+vals)
    lines += [markdown(['Model','ICS2 drift in','ICS2 drift out','Baseline forgetting pp','FAP2 restored pp','FAP16 restored pp','ID2 restored pp','ID16 restored pp'],E),'','Fixed display: stage3→4 old test RoIs for absolute mean squared drift; stage4←j equal mean over three old domains for retrieval forgetting. Common basis reference: F_stage1 fit videos, with destination stored PCS for ICS2. Full transitions, ranks2/8/16, per-RoI energy fractions, LaTeX and the two-panel figure are in `ics_probe/drift_decomposition/`. No coordinate alignment is applied. HF differs from F in high-frequency noise and APR coupling, so this contrast alone does not isolate coupling. Run, checkpoints stage1–4 epoch5, seed0 and source commit are above.','','## Table F — inference-time interventions','', 'Each value is the equal mean of four target-domain metrics; parentheses are changes from that model’s beta0 in percentage points. OVERALL is the official per-domain class-combined metric, followed by the domain mean. Every individual domain and all six classes are delivered.','',markdown(['Model','Class','Basis','beta','HOTA (Δ)','DetA (Δ)','IDF1 (Δ)','AssA (Δ)'],[[r['checkpoint'],r['category'],r['basis'],r['beta']]+[n(r[m+'_percent'])+' ('+('%+.3f'%float(r['delta_'+m+'_pp']))+')' for m in METRICS] for r in F]),'', 'Source: `ics_followup_20261029/tables/table_F_all_domains.csv`, `S4_full_class_metrics.csv`, and `S4/`. Checkpoints F/HF stage4 epoch5; basis seed9973, fit split seed0; run and source commit above. All native beta0 frame outputs match replay exactly. F uses the user-approved fresh V100 baseline; all old/new differences and the failed historical gate are preserved. Re-evaluating old F predictions exactly recovers old HOTA/DetA/AssA. HF matches its frozen V100 metrics. Enabled native-head projection and replay are also checked on the predeclared first Overcast video (ICS2 beta.5, identity16 beta1). No post-projection normalization is added.','','## Table G — Night-only 2×2, two epochs','',markdown(['Group','Class','Estimator','Coupled','Night HOTA','Night IDF1','Night AssA','Old HOTA','HOTA forgetting pp','IDF1 forgetting pp','AssA forgetting pp'],[[r['group'],r['category'],r['estimator'],r['coupling']]+[n(r[k]) for k in ['night_HOTA_percent','night_IDF1_percent','night_AssA_percent','old_mean_HOTA_percent','old_mean_forgetting_HOTA_pp','old_mean_forgetting_IDF1_pp','old_mean_forgetting_AssA_pp']] for r in G]),'', 'Source: `ics_followup_20261029/tables/table_G_all_domains.csv`, `table_G_forgetting.csv`, `table_G_summary.csv`, `S5_factorial_effects.csv`, and `S5_bank_updates_and_insufficient_pairs.csv`. DetA and all individual domains/classes are included in the full CSV. Forgetting is stage3 minus the two-epoch endpoint, with no clipping; these endpoints are not a controlled absolute comparison to five-epoch runs. Coupling contrasts are a−b and c−d; estimator contrasts are c−a and d−b. Subspace properties are in Table C.','',f'All groups start from HF stage3 epoch5 (SHA256 `0dbc117207f248eae2632bffe382d38dc0e0cc67409d44986399ae67a2a9090b`) with the same saved rank0 APR history (SHA256 `a8c2ea74e8d0d9aed6e069f9a7cb338bd0f39599a2e9f455dc07f8a6d2cf74bc`), seed1790355234 and inherited bank updates660. Minimum samples96 and all HF geometry/LF/HF settings are retained. Per-rank start/end updates and every insufficient-pairs check are saved. Run: `{ROOT}/results/S5/HF_{{a,b,c,d}}`; source commit above.','', '<!-- ICS_FOLLOWUP_END -->']
    doc=PUB/'experiments/SUMMARY_20261029.md';old=doc.read_text();start=old.index('<!-- ICS_FOLLOWUP_BEGIN -->');end=old.index('<!-- ICS_FOLLOWUP_END -->')+len('<!-- ICS_FOLLOWUP_END -->');doc.write_text(old[:start]+'\n'.join(lines)+old[end:])
    write_json(DEST/'status.json',dict(status='complete',S1=True,S2=True,S3=True,S4=True,S5_primary_four_groups=True,optional_NOGEOM_short_repeat='not run',run=str(ROOT),method_source_commit=code,completed_UTC=time.strftime('%Y-%m-%d %H:%M:%S',time.gmtime()),selection_by_metric=False))
    (DEST/'README.md').write_text('''# Completed ICS follow-up\n\nAll required primary S1–S5 experiments are complete. The five result tables and input/checkpoint/seed/source provenance are in `../SUMMARY_20261029.md`; full tables are in `tables/`. Original v1 results remain intact.\n\nThe user approved two protocol resolutions: report stored bank_pcs separately from covariance eigenspaces when the original <1 degree gate fails; and use fresh native V100 beta0 for F tracking interventions while disclosing every old/new difference. Thresholds and seeds were not tuned. The failed checks, diagnostics and decisions are retained.\n\nS1 configurations contain effective model pipelines and data.train pipelines. NOGEOM has no active stochastic geometry. Offline probes fix geometry and use exactly the same RoIs as F. S2 uses raw projected car/test vectors for Fisher, a complete multi-rank scan, ten random bases for P3, all P2 binary spaces and the Full confusion matrix. P1 retains its original fifty-basis random control. BDD domain offsets are unpaired and include scene/identity differences.\n\nS3 uses the literal common F stage1 fit reference and test statistics; drift shares are per-RoI fraction means over nonzero drifts, with absolute in/out energies also exported. Every transition and restoration dimension is retained. Retrieval forgetting is a proxy; tracking forgetting is measured separately in S5.\n\nS4 replays the unchanged native tracker using original FP32 embeddings/detections. Native beta0 output equality and reference metrics are checked before nonzero beta. Independent enabled-head checks cover the predeclared first Overcast video at ICS2 beta.5 and identity16 beta1. Projection applies to all association embeddings, with no added normalization; bases are estimated from car RoIs. FAP2 uses clear fit videos only. Detector outputs stay fixed, while native track acceptance can change DetA.\n\nS5 executes only Night for two epochs, from the same complete HF stage3 checkpoint, same historical APR prototypes and seed. Inherited banks are checked before the first update; every insufficient-pairs event is counted. Storage changes retain the final epoch and omit optimizer serialization. Exact historical APR vectors were available in rank-local runtime sidecars despite the absence of a <stage>_roi_proto.pth filename, so no approximate reconstruction is used. The optional NOGEOM short-training repeat was not run.\n\nSmall .npy files contain projection bases. Raw .npz features, model weights, large prediction caches and full local source archives remain on the server. Per-job fingerprints, configurations, metadata, logs, CSV and LaTeX are delivered. Operational scripts use the documented RUN/code layout and explicit read-only input roots.\n''')
    files=[f for base in [DEST,PUB/'experiments/ics_probe'] for f in sorted(base.rglob('*')) if f.is_file() and f.name!='SHA256SUMS']+[doc]
    assert not any(f.suffix in ['.pth','.npz','.pt','.ckpt'] for f in files)
    (DEST/'SHA256SUMS').write_text(''.join(hashlib.sha256(f.read_bytes()).hexdigest()+'  '+str(f.relative_to(PUB))+'\n' for f in files));print('Final result bundle staged',len(files),'files')
if __name__=='__main__':main()
